window.kbPageData["views/entry/k-3a208c42ed1b69b4"] = {"key":"entry/k-3a208c42ed1b69b4","state":{"route":"entry/k-3a208c42ed1b69b4"},"node":{"id":"k-3a208c42ed1b69b4","mode":"k","title":"逆否等价","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["条件命题与其逆否命题等价"],"qs":["江苏 2024 B类 行测#91","江苏 2024 C类 行测#91","江苏 2025 A类 行测#91","江苏 2025 B类 行测#102","江苏 2025 C类 行测#91"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":3,"directorySummary":"条件命题“如果 P，那么 Q”与它的逆否命题“如果 Q 不成立，那么 P 不成立”逻辑等价。","review":{"title":"逆否等价","type":"原理与机制","definition":"条件命题“如果 P，那么 Q”与它的逆否命题“如果 Q 不成立，那么 P 不成立”逻辑等价。","explanation":"两者都只在 P 成立而 Q 不成立时为假。若被否定的是由“且”连接的复合条件，其否定表示其中至少一项不成立。","basis":"据关联原题和解析编释。","references":[],"related":["k-4aa308d0488924b5"],"examFocus":{"江苏 2024 B类 行测#91":"辨明“除非……否则……”中的必要条件，判断哪些陈述可由原句推出。","江苏 2025 A类 行测#91":"区分“只有……才……”和“只要……就……”的推理方向，辨清复合条件的否定范围。","江苏 2025 B类 行测#102":"将备选前提代入已知条件，用逆否推理检验能否推出指定结论。"}},"aspects":[{"title":"必要条件的逆否推理","uses":[{"unit":"Q1","role":"解题依据","use":"飞向天空以两翼健壮且共同发力为必要条件。②重述这一条件关系，③指出任一条件不满足就不能飞向天空，因此选B。","evidence":"③一只鸟若两翼不健壮或不能以共同的力量来推动身体，那么它不能飞向天空","qids":["江苏 2024 B类 行测#91","江苏 2024 C类 行测#91"]},{"unit":"Q2","role":"解题依据","use":"题干把“为了人民”设为现代化有意义的必要条件，否定这一条件即可推出A项。若未能充分调动人民积极性，只能推出“为了人民”和“依靠人民”至少有一项未坚持，C项指定前一项，超出了可推出的范围。","evidence":"只有为了人民的现代化，才有意义","qids":["江苏 2025 A类 行测#91","江苏 2025 C类 行测#91"]}]},{"title":"多条件推理中的逆否命题","uses":[{"unit":"Q3","role":"解题依据","use":"补入D项后，由小周是经济学专业的推出小赵不是哲学专业的，再推出小钱是法医专业的。由此推出小孙不是计算机专业的，结合小李和小孙至少有一人是计算机专业的，得到小李是计算机专业的。两次逆否推理分别用到条件（1）和（4）。","evidence":"根据条件①可知：想要推出“小赵不是哲学专业的”，根据“逆否等价”，需要“小周是经济学专业的”成立，对应D项。","qids":["江苏 2025 B类 行测#102"]}]}]},"questions":{"江苏 2024 B类 行测#91":{"paper":"江苏 2024 B类 行测","n":91,"mod":"判断推理","src":["0ae7ac475476e5635bd7.pdf",18],"asrc":["8dd171daee6fc74e9718.pdf",30],"card":"be8ce75a5a76ea90e5d7ee29","links":[{"id":"k-3a208c42ed1b69b4","role":"解题依据","why":"可以通过否定后件推出对前件的否定。"}]},"江苏 2024 C类 行测#91":{"paper":"江苏 2024 C类 行测","n":91,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",19],"asrc":["02d6b49839583bdaf297.pdf",27],"card":"79fa5756e135d438d56147d7","links":[{"id":"k-3a208c42ed1b69b4","role":"直接考查","why":"否定必要条件即可推出相应结果不成立。"}]},"江苏 2025 A类 行测#91":{"paper":"江苏 2025 A类 行测","n":91,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",19],"asrc":["4fe8e0544dd7b47699d2.pdf",29],"card":"c50bad3725bd889ab4b27bdd","links":[{"id":"k-3a208c42ed1b69b4","role":"解题依据","why":"若前件推出后件，否定后件即可推出对前件的否定。"}]},"江苏 2025 B类 行测#102":{"paper":"江苏 2025 B类 行测","n":102,"mod":"判断推理","src":["91e0d9fd02ca7ec6d61f.pdf",21],"asrc":["f2ff67a0f2a2f7e8e926.pdf",34],"card":"3c3a3de16e682ac8f2b3aac3","links":[{"id":"k-3a208c42ed1b69b4","role":"解题依据","why":"两条条件命题都需要通过否定后件推出否定前件。"}]},"江苏 2025 C类 行测#91":{"paper":"江苏 2025 C类 行测","n":91,"mod":"判断推理","src":["ffc394a1c160f331ec57.pdf",19],"asrc":["d1de3b437151c05b769e.pdf",27],"card":"e0f38f4af48bc6628c38e8f2","links":[{"id":"k-3a208c42ed1b69b4","role":"解题依据","why":"若前件蕴含后件，否定后件即可推出否定前件。"}]}},"terms":{"k-4aa308d0488924b5":{"id":"k-4aa308d0488924b5","mode":"k","type":"原理与机制","title":"否定后件式","qs":[],"count":2}},"references":{},"topics":[],"units":{"k-3a208c42ed1b69b4":[["江苏 2024 B类 行测#91","江苏 2024 C类 行测#91"],["江苏 2025 A类 行测#91","江苏 2025 C类 行测#91"],["江苏 2025 B类 行测#102"]]}};
